// BulkheadConfiguration.java
@Configuration
public class BulkheadConfiguration {

    @Bean
    public ThreadPoolBulkhead claimProcessingBulkhead() {
        ThreadPoolBulkheadConfig config = ThreadPoolBulkheadConfig.custom()
            .maxThreadPoolSize(50)
            .coreThreadPoolSize(25)
            .queueCapacity(100)
            .keepAliveDuration(Duration.ofSeconds(30))
            .build();

        return ThreadPoolBulkhead.of("claimProcessing", config);
    }

    @Bean
    public ThreadPoolBulkhead ediGatewayBulkhead() {
        ThreadPoolBulkheadConfig config = ThreadPoolBulkheadConfig.custom()
            .maxThreadPoolSize(30)
            .coreThreadPoolSize(15)
            .queueCapacity(50)
            .keepAliveDuration(Duration.ofSeconds(60))
            .build();

        return ThreadPoolBulkhead.of("ediGateway", config);
    }

    @Bean
    public SemaphoreBulkhead reportingBulkhead() {
        SemaphoreBulkheadConfig config = SemaphoreBulkheadConfig.custom()
            .maxConcurrentCalls(10)
            .maxWaitDuration(Duration.ofMillis(500))
            .build();

        return SemaphoreBulkhead.of("reporting", config);
    }
}

// ClaimService.java
@Service
public class ClaimService {

    @Autowired
    private ThreadPoolBulkhead claimProcessingBulkhead;

    @Autowired
    private CircuitBreaker circuitBreaker;

    public CompletableFuture<ClaimResult> processClaim(String claimId) {
        // Combine bulkhead with circuit breaker
        Supplier<ClaimResult> supplier = () -> processClaimSync(claimId);

        Supplier<ClaimResult> decoratedSupplier = Decorators
            .ofSupplier(supplier)
            .withThreadPoolBulkhead(claimProcessingBulkhead)
            .withCircuitBreaker(circuitBreaker)
            .withFallback(Arrays.asList(
                BulkheadFullException.class,
                CallNotPermittedException.class
            ), ex -> getFallbackClaimResult(claimId, ex))
            .decorate();

        return CompletableFuture.supplyAsync(decoratedSupplier);
    }

    private ClaimResult processClaimSync(String claimId) {
        // Actual claim processing logic
        log.info("Processing claim: {}", claimId);
        Claim claim = claimRepository.findById(claimId);
        return claimProcessor.adjudicate(claim);
    }

    private ClaimResult getFallbackClaimResult(String claimId, Throwable ex) {
        log.warn("Bulkhead exhausted for claim {}, returning cached result", claimId, ex);
        return claimCache.getOrDefault(claimId, ClaimResult.unavailable());
    }
}
```

**C# Implementation with Polly:**

```csharp
// BulkheadConfiguration.cs
public class BulkheadConfiguration
{
    public static IAsyncPolicy<ClaimResult> GetClaimProcessingPolicy()
    {
        var bulkhead = Policy.BulkheadAsync<ClaimResult>(
            maxParallelization: 50,
            maxQueuingActions: 100,
            onBulkheadRejectedAsync: context =>
            {
                _logger.LogWarning("Claim processing bulkhead rejected request");
                _metrics.RecordBulkheadRejection("claimProcessing");
                return Task.CompletedTask;
            });

        var circuitBreaker = Policy
            .Handle<Exception>()
            .CircuitBreakerAsync(
                handledEventsAllowedBeforeBreaking: 5,
                durationOfBreak: TimeSpan.FromSeconds(30));

        var fallback = Policy<ClaimResult>
            .Handle<BulkheadRejectedException>()
            .FallbackAsync(
                fallbackValue: ClaimResult.Unavailable(),
                onFallbackAsync: (result, context) =>
                {
                    _logger.LogWarning("Fallback triggered for claim processing");
                    return Task.CompletedTask;
                });

        return Policy.WrapAsync(fallback, bulkhead, circuitBreaker);
    }
}

// ClaimService.cs
public class ClaimService
{
    private readonly IAsyncPolicy<ClaimResult> _claimProcessingPolicy;

    public ClaimService()
    {
        _claimProcessingPolicy = BulkheadConfiguration.GetClaimProcessingPolicy();
    }

    public async Task<ClaimResult> ProcessClaimAsync(string claimId)
    {
        return await _claimProcessingPolicy.ExecuteAsync(async () =>
        {
            _logger.LogInformation("Processing claim: {ClaimId}", claimId);
            var claim = await _claimRepository.GetByIdAsync(claimId);
            return await _claimProcessor.AdjudicateAsync(claim);
        });
    }
}
