##### Step 5: Configure Monitoring and Alerting

**Prometheus Metrics Export:**

```java
// BulkheadMetrics.java
@Component
public class BulkheadMetrics {

    private final MeterRegistry registry;

    public BulkheadMetrics(MeterRegistry registry,
                          ThreadPoolBulkhead claimBulkhead,
                          ThreadPoolBulkhead ediBulkhead) {
        this.registry = registry;

        // Register bulkhead metrics
        Gauge.builder("bulkhead.available.threads", claimBulkhead,
                b -> b.getMetrics().getAvailableConcurrentCalls())
            .tag("bulkhead", "claimProcessing")
            .register(registry);

        Gauge.builder("bulkhead.queue.size", claimBulkhead,
                b -> b.getMetrics().getQueueDepth())
            .tag("bulkhead", "claimProcessing")
            .register(registry);

        Counter.builder("bulkhead.rejected.total")
            .tag("bulkhead", "claimProcessing")
            .register(registry);
    }

    public void recordRejection(String bulkheadName) {
        registry.counter("bulkhead.rejected.total",
            "bulkhead", bulkheadName).increment();
    }
}
```

**Prometheus Alert Rules:**

```yaml
# bulkhead-alerts.yml
groups:

- name: bulkhead_alerts
  interval: 30s
  rules:

  - alert: BulkheadHighUtilization
    expr: bulkhead_available_threads / bulkhead_max_threads < 0.2
    for: 5m
    labels:
      severity: warning
      component: bulkhead
    annotations:
      summary: "Bulkhead {{ $labels.bulkhead }} high utilization"
      description: "Bulkhead {{ $labels.bulkhead }} has less than 20% threads available for {{ $value }}s"

  - alert: BulkheadExhausted
    expr: bulkhead_available_threads == 0
    for: 2m
    labels:
      severity: critical
      component: bulkhead
    annotations:
      summary: "Bulkhead {{ $labels.bulkhead }} exhausted"
      description: "Bulkhead {{ $labels.bulkhead }} has no available threads"

  - alert: BulkheadHighRejectionRate
    expr: rate(bulkhead_rejected_total[5m]) > 10
    for: 5m
    labels:
      severity: warning
      component: bulkhead
    annotations:
      summary: "High rejection rate for bulkhead {{ $labels.bulkhead }}"
      description: "Bulkhead {{ $labels.bulkhead }} rejecting {{ $value }} requests/sec"

  - alert: BulkheadQueueBackup
    expr: bulkhead_queue_size / bulkhead_queue_capacity > 0.8
    for: 5m
