        ThreadPoolBulkhead bulkhead = tenantBulkheads.get(stateCode);
        BulkheadMetrics metrics = bulkhead.getMetrics();

        double utilization = (double) metrics.getMaxAllowedParallelExecutions()
                           / metrics.getAvailableConcurrentCalls();

        if (utilization > 0.90) {
            // High utilization - consider increasing quota
            log.warn("State {} bulkhead at {}% utilization", stateCode, utilization * 100);
            metricsService.recordHighUtilization(stateCode, utilization);

            // Alert ops team for capacity evaluation
            alertService.sendAlert(AlertLevel.WARNING,
                "Tenant " + stateCode + " may need quota increase");
        } else if (utilization < 0.30) {
            // Low utilization - consider decreasing quota for efficiency
            log.info("State {} bulkhead underutilized at {}%", stateCode, utilization * 100);
        }
    }
}
